import org.jsoup.nodes.*;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class AttributesTests {

    @Test
    public void indexOfKeyTest() {
        Attributes attrs = new Attributes();
        attrs.add("key", "value");
        int index = attrs.indexOfKey("key");
        assertEquals(0, index);
    }

    @Test
    public void checkNotNullTest() {
        Object val = Attributes.checkNotNull("value");
        assertEquals("value", val);
    }

    @Test
    public void getTest() {
        Attributes attrs = new Attributes();
        attrs.add("key", "value");
        String value = attrs.get("key");
        assertEquals("value", value);
    }

    @Test
    public void getIgnoreCaseTest() {
        Attributes attrs = new Attributes();
        attrs.add("KEY", "value");
        String value = attrs.getIgnoreCase("key");
        assertEquals("value", value);
    }

    @Test
    public void addTest() {
        Attributes attrs = new Attributes();
        attrs.add("key", "value");
        String value = attrs.get("key");
        assertEquals("value", value);
    }

    @Test
    public void putTest() {
        Attributes attrs = new Attributes();
        attrs.put("key", "value");
        String value = attrs.get("key");
        assertEquals("value", value);
    }

    @Test
    public void putUserDataTest() {
        Attributes attrs = new Attributes();
        attrs.putUserData("key", "value");
        Object value = attrs.getUserData("key");
        assertEquals("value", value);
    }

    @Test
    public void putIgnoreCaseTest() {
        Attributes attrs = new Attributes();
        attrs.putIgnoreCase("KEY", "value");
        String value = attrs.getIgnoreCase("key");
        assertEquals("value", value);
    }

    @Test
    public void removeTest() {
        Attributes attrs = new Attributes();
        attrs.add("key", "value");
        attrs.remove("key");
        assertFalse(attrs.hasKey("key"));
    }

    @Test
    public void removeIgnoreCaseTest() {
        Attributes attrs = new Attributes();
        attrs.add("KEY", "value");
        attrs.removeIgnoreCase("key");
        assertFalse(attrs.hasKeyIgnoreCase("key"));
    }

    @Test
    public void hasKeyTest() {
        Attributes attrs = new Attributes();
        attrs.add("key", "value");
        assertTrue(attrs.hasKey("key"));
    }

    @Test
    public void isEmptyTest() {
        Attributes attrs = new Attributes();
        assertTrue(attrs.isEmpty());
        attrs.add("key", "value");
        assertFalse(attrs.isEmpty());
    }

    @Test
    public void addAllTest() {
