        attrs.add("key", "value");
        String html = attrs.html();
        assertTrue(html.contains("key=\"value\""));
    }

    @Test
    public void cloneTest() {
        Attributes attrs = new Attributes();
        attrs.add("key", "value");
        Attributes clonedAttrs = attrs.clone();
        assertTrue(clonedAttrs.hasKey("key"));
    }

